/* Checklist roll-up: a task's % comes from its checklist (or a % set by hand when it has none), then rolls up into tasks, phases and the programme summary. Programme items come from the Get Prog Items data table node. */
const S=v=>v==null?'':String(v).trim();const jk=v=>S(v).replace(/[^0-9A-Za-z]/g,'').toLowerCase();
const j=Object.assign({},$input.first().json);
const ckl=t=>{try{const a=JSON.parse(S(t.checklist_json)||'[]');return Array.isArray(a)?a.filter(i=>i&&S(i.t)):[];}catch(e){return [];}};
const man=t=>{const p=S(t.pct);if(p===''||isNaN(Number(p))||Number(p)===0)return null;return Math.max(0,Math.min(100,Math.round(Number(p))));};
function leafPct(t,base){const ck=ckl(t);if(ck.length){const d=ck.filter(i=>i.done).length;const st=d===ck.length?'Done':(d>0||S(t.status)==='In progress'?'In progress':'Not started');return {pct:Math.round(100*d/ck.length),st:st,ck:ck,d:d};}
 const st=S(t.status)||'Not started';if(st==='Done')return {pct:100,st:st,ck:[],d:0};const m=man(t);return {pct:m!=null?m:base(st),st:st,ck:[],d:0};}
if(Array.isArray(j.phases)){
 const today=S(j.today);
 const fix=(t,base)=>{const r=leafPct(t,base);t.pct=r.pct;t.status_eff=r.st;t.checklist=r.ck;t.ck_done=r.d;t.ck_total=r.ck.length;t.overdue=!!t.end_eff&&t.end_eff<today&&t.status_eff!=='Done';};
 const roll=(p,kids)=>{p.pct=Math.round(kids.reduce((m,x)=>m+x.pct,0)/kids.length);p.status_eff=kids.every(x=>x.status_eff==='Done')?'Done':((p.pct>0||kids.some(x=>x.status_eff!=='Not started'))?'In progress':'Not started');p.overdue=!!p.end_eff&&p.end_eff<today&&p.pct<100&&p.status_eff!=='Done';};
 const leaves=[];
 j.phases.forEach(p=>{(p.tasks||[]).forEach(t=>{if((t.subs||[]).length){t.subs.forEach(x=>{fix(x,()=>0);leaves.push(x);});roll(t,t.subs);}else{fix(t,()=>0);leaves.push(t);}});
