/* Start date: handles set_start (planned start, works before a programme exists) and, after any programme change, keeps the job's start (cbs_jobs.starts_on) equal to the earliest task date while the programme is live. A ServiceM8 booking still takes priority wherever the start is shown. */
const h=this.helpers,H='https://old-hub.example/webhook/',K='[redacted-internal-key]';
const S=v=>v==null?'':String(v).trim();const jk=v=>S(v).replace(/[^0-9A-Za-z]/g,'').toLowerCase();const num=v=>Number(v)||0;
const isD=v=>/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(S(v));
const res=$input.first().json||{};const b=$('Act Hook').first().json.body||{};
const a=S(b.a),job=S(b.job).replace(/[^0-9A-Za-z-]/g,''),by=S(b.by);
const list=async t=>{const L=await h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=list&t='+t,body:{},json:true,timeout:20000});return (Array.isArray(L)?L:[]).filter(r=>r&&r.id!=null);};
const save=(t,id,row)=>h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t='+t+'&id='+id+'&k='+K+'&partial=1',body:row,json:true,timeout:20000});
const jobRow=async()=>(await list('jobrows')).filter(r=>jk(r.ref)===jk(job)).sort((x,y)=>num(y.id)-num(x.id))[0]||null;
if(a==='set_start'){
 if(!job)return [{json:{ok:false,message:'No job number.'}}];if(!by)return [{json:{ok:false,message:'Enter your name.'}}];
 const st=S(b.start_on);if(st&&!isD(st))return [{json:{ok:false,message:'Check the date.'}}];
