try{const P=(await list('programmes')).filter(p=>jk(p.job_no)===jk(job)).sort((x,y)=>num(y.id)-num(x.id))[0];
 if(P&&S(P.status)==='Open'){const st=(await list('progitems')).filter(r=>jk(r.job_no)===jk(job)).map(r=>S(r.start_on)).filter(isD).sort()[0]||'';
